package com.dpworld.fms.simulator;
import com.dpworld.fms.domain.*; import java.time.*; import java.util.*; import java.util.stream.*;
public final class SampleFleetFactory { public List<Asset> create(int count){if(count<1||count>1500)throw new IllegalArgumentException("simulator asset count must be 1..1500");var random=new Random(42);return IntStream.range(0,count).mapToObj(i->new Asset(UUID.nameUUIDFromBytes(("asset-"+i).getBytes()),"ITV-%04d".formatted(i+1),i%10==0?AssetType.TRACTOR:AssetType.ITV,new GeoPoint(24.985+random.nextDouble()*.025,55.02+random.nextDouble()*.035),random.nextDouble()*360,10+random.nextDouble()*30,i%7==0?AssetStatus.WORKING:AssetStatus.IDLE,i%7==0?Availability.ASSIGNED:Availability.AVAILABLE,20+random.nextDouble()*80,random.nextDouble()*100000,random.nextDouble()*10000,"YARD-"+(i%5),null,Instant.now(),"DRV-"+i,"DEV-"+i,"TRACKIT-"+i,MaintenanceStatus.SERVICEABLE,Set.of("TWISTLOCK","PORT_ROAD"),new VehicleEnvelope(3.2,2.5,7,35))).toList();} }
